import * as React from "react";

export type ReelTapeIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function ReelTapeIcon({ size = 20, ...props }: ReelTapeIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <circle cx="7.5" cy="8" r="3.5" /><circle cx="16.5" cy="8" r="3.5" /><path d="M4 16.5h16M7.5 11.5V16M16.5 11.5V16" />
    </svg>
  );
}
